import { BRAND } from "@/lib/brand";

export interface BlogPost {
  slug: string;
  title: string;
  excerpt: string;
  publishedAt: string;
  readTime: string;
  author: { name: string; role: string };
  category: "ops" | "compliance" | "craft" | "product";
  gradient: string;
}

